  const b = book();
  const r = b.refund({ merchantId: 'm_1', chargeId: 'ch_1', amountMinor: 100, idempotencyKey: 'k' });
  r.amountMinor = 1;
  assert.equal(b.refund({ merchantId: 'm_1', chargeId: 'ch_1', amountMinor: 100, idempotencyKey: 'k' }).amountMinor, 100);
});

